 function visible(){dragon.hide();for(const n of fauna.actors)n.g.visible=n.hp>0;for(const [key,g] of Object.entries(roots))g.visible=key===mode;villageGate.visible=!mode;scene.fog&&(scene.fog.density=mode?.008:.018);for(const l of labels.values())l.hidden=true}
 function enter(which,pose){if(!C2_REGIONS[which])return false;if(!mode)origin=getPose?.()||{position:[0,1.7,-115],yaw:0,pitch:0};combat.clear();build(which);mode=which;visible();setPose(pose||{position:C2_REGIONS[which].entry,yaw:0,pitch:0});label();fauna.visit(which,C2_REGIONS[which].x);if(which==='city'&&raid.active)for(const n of all.filter(n=>n.group==='raid'&&n.hp>0).slice(0,3))n.aggro=camera.position.clone();if(which==='road'&&story.roadOpen&&all.filter(n=>n.zone==='road'&&n.group==='road').every(n=>n.hp<=0))revive(all.filter(n=>n.zone==='road'&&n.group==='road'));return true}
