 function setStory(s){story=s||{};if(roadGate){roadGate.visible=!story.roadOpen;roadGate.userData.block.disabled=!!story.roadOpen}if(cart)cart.visible=!!story.followCart;if(prisonGate)prisonGate.visible=!story.cellarOpen;for(const n of npcs){if(['c2-caravan-city','c2-anna-city'].includes(n.id))n.g.visible=!!story.roadOpen;else if(['c2-caravan','c2-refugee-anna','c2-refugee-old'].includes(n.id))n.g.visible=!story.roadOpen;else if(n.id==='c2-order')n.g.visible=!!story.orderPresent;else if(n.id==='c2-city-courier')n.g.visible=!!story.courierFreed;else if(n.id==='c2-prisoner'||n.id==='c2-prisoner-woman')n.g.visible=story.route!=='tail'&&!story.courierFreed;else if(n.id==='c2-manor-courier')n.g.visible=story.route==='tail'&&!story.courierFreed}for(const n of all)if(n.zone==='inn'&&n.group==='inn')n.g.visible=n.hp>0&&(!!story.innHostile||cartAlerted&&story.followCart&&['c2-inn-0','c2-inn-1'].includes(n.id))}
 function action(){if(!mode)return Math.hypot(camera.position.x,camera.position.z+118)<3.4?{type:'enter'}:null;const x=C2_REGIONS[mode].x,z=camera.position.z,near=(xx,zz,r=3)=>Math.hypot(camera.position.x-xx,z-zz)<r;if(mode==='road'){if(near(x,-18))return {type:'village'};if(near(x,-234))return {type:'travel',to:'city'}}if(mode==='city'){if(near(x,-20))return {type:'travel',to:'road',back:true};if(near(x,-224))return {type:'travel',to:story.manorShortcut?'manor':'inn'}}if(mode==='inn'){if(near(x,-18))return {type:'travel',to:'city',back:true};if(near(x,-181))return {type:'travel',to:'manor'};if(near(x+6,-139))return {type:'cellar'};if(near(x+55,-145))return {type:'cellar_exit'}}if(mode==='manor'){if(near(x,-18))return {type:'travel',to:'city',back:true};const i=lanterns.findIndex(l=>!l.lit&&camera.position.distanceTo(l.g.position)<3);if(i>=0)return {type:'lantern',index:i}}const f=fires.find(f=>f.zone===mode&&near(f.x,f.z,3));if(f)return {type:'checkpoint',fire:f};const c=chests.find(c=>c.zone===mode&&camera.position.distanceTo(c.g.position)<3);if(c)return {type:'chest',chest:c};const n=npcs.filter(n=>n.zone===mode&&n.g.visible&&camera.position.distanceTo(n.g.position)<3.6).sort((a,b)=>camera.position.distanceTo(a.g.position)-camera.position.distanceTo(b.g.position))[0];return n?{type:'npc',npc:n}:null}
