 function killed(n){if(fauna.killed(n))return;if(!all.includes(n)||n.droppedGeneration===n.generation)return;n.droppedGeneration=n.generation;n.g.visible=false;if(n.role==='vampire'){combat.clear();for(const a of all.filter(a=>a.group==='boss-add')){a.hp=0;a.g.visible=false}}drop('gold',n.role==='vampire'?45:3+Math.floor(rand()*6),n.g.position);if(n.role==='vampire')drop('vampire_signet',1,n.g.position.clone().add(new T.Vector3(.7,0,0)));else drop('cult_sign',1,n.g.position.clone().add(new T.Vector3(.6,0,0)));if(n.group==='farm'||n.group==='road'&&story.roadOpen){const group=all.filter(a=>a.zone===n.zone&&a.group===n.group);if(group.filter(a=>a.hp<=0).length>=Math.ceil(group.length*.7))revive(group.filter(a=>a!==n&&a.hp<=0))}}
